      { q: "A slow request's trace shows <code>db.pool.acquire</code> 2.6 s and <code>INSERT</code> 15 ms. Where's the problem?", options: ["The database is slow", "Waiting for a free connection in the app's pool", "The network", "Redis"], answer: 1, why: "The query is fast; getting a connection isn't." },
      { q: "How did you instrument the apps here?", options: ["Rewrote them", "Set OTEL_* environment variables for the already-included SDK", "Installed a sidecar proxy", "Changed the Ingress"], answer: 1, why: "OpenTelemetry SDKs are configured by standard env variables." }
